// Input (optional): the message, then the shift number.
function shift(text, key) {
  return text.replace(/[a-z]/gi, (ch) => {
    const base = ch <= "Z" ? 65 : 97;
    return String.fromCharCode(((ch.charCodeAt(0) - base + key) % 26 + 26) % 26 + base);
  });
}

// Try all 26 keys and keep the one whose result looks most like English.
function crack(secret) {
  const common = "etaoinshr";
  let best = 0, bestScore = -1;
  for (let key = 0; key < 26; key++) {
    const plain = shift(secret, -key).toLowerCase();
    const score = [...plain].filter((c) => common.includes(c)).length;
    if (score > bestScore) { best = key; bestScore = score; }
  }
  return best;
}

