// Add numbers or numerals (like 2024 or MCMXCIV) in Run Settings › Input.
const TABLE = [[1000, "M"], [900, "CM"], [500, "D"], [400, "CD"], [100, "C"], [90, "XC"],
  [50, "L"], [40, "XL"], [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];

function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) throw new Error("Use a whole number from 1 to 3999");
  let out = "";
  for (const [value, symbol] of TABLE) while (n >= value) { out += symbol; n -= value; }
  return out;
}

function fromRoman(text) {
  let total = 0, rest = text.toUpperCase();
  for (const [value, symbol] of TABLE) while (rest.startsWith(symbol)) { total += value; rest = rest.slice(symbol.length); }
  if (rest || toRoman(total) !== text.toUpperCase()) throw new Error(`${text} isn't a valid Roman numeral`);
  return total;
}

