function bubble(input) {
  const a = [...input];
  let steps = 0;
  for (let end = a.length - 1; end > 0; end--) {
    for (let i = 0; i < end; i++) {
      steps++;
      if (a[i] > a[i + 1]) [a[i], a[i + 1]] = [a[i + 1], a[i]];
    }
    show(a, `largest ${a[end]} bubbled to the end`);
  }
  return steps;
}

function insertion(input) {
  const a = [...input];
  let steps = 0;
  for (let i = 1; i < a.length; i++) {
    const item = a[i];
    let j = i - 1;
    while (j >= 0 && a[j] > item) { a[j + 1] = a[j]; j--; steps++; }
    a[j + 1] = item;
    show(a, `inserted ${item}`);
  }
  return steps;
}

function quick(input) {
  let steps = 0;
  const sort = (a) => {
    if (a.length <= 1) return a;
    const [pivot, ...rest] = a;
    steps += rest.length;
    return [...sort(rest.filter((x) => x < pivot)), pivot, ...sort(rest.filter((x) => x >= pivot))];
  };
  show(sort(input), "sorted by splitting around pivots");
  return steps;
}

