// Input (optional): the number to look for.
function binarySearch(items, target) {
  let low = 0, high = items.length - 1, steps = 0;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    steps++;
    console.log(`  step ${steps}: position ${mid} holds ${items[mid]} (searching ${low}–${high})`);
    if (items[mid] === target) return { index: mid, steps };
    if (items[mid] < target) low = mid + 1; else high = mid - 1;
  }
  return { index: -1, steps };
}

