function memoize(fn) {
  const cache = new Map();
  return (n) => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}
const fibFast = memoize((n) => (n < 2 ? n : fibFast(n - 1) + fibFast(n - 2)));

