// Input (optional): the limit.
function sieve(limit) {
  const isPrime = Array(limit + 1).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let n = 2; n * n <= limit; n++) {
    if (isPrime[n]) for (let multiple = n * n; multiple <= limit; multiple += n) isPrime[multiple] = false;
  }
  return isPrime.flatMap((prime, n) => (prime ? [n] : []));
}

function factors(n) {
  const out = [];
  for (let d = 2; d * d <= n; d++) while (n % d === 0) { out.push(d); n /= d; }
  if (n > 1) out.push(n);
  return out;
}

