// Edit the maze: # is a wall, S the start, E the end.
const MAZE = `
##########
#S   #   #
# ## # # #
# #    # #
# #### # #
#    #   #
#### # ###
#      E #
##########`.trim().split("\n");

function find(char) {
  for (let r = 0; r < MAZE.length; r++) if (MAZE[r].includes(char)) return [r, MAZE[r].indexOf(char)];
}

function solve() {
  const start = find("S"), end = find("E");
  const cameFrom = new Map([[start.join(), null]]);
  const queue = [start];
  while (queue.length) {
    const [r, c] = queue.shift();
    if (r === end[0] && c === end[1]) {
      const path = [];
      for (let at = end.join(); at; at = cameFrom.get(at)) path.push(at);
      return path.reverse();
    }
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (MAZE[nr][nc] !== "#" && !cameFrom.has(`${nr},${nc}`)) {
        cameFrom.set(`${nr},${nc}`, `${r},${c}`);
        queue.push([nr, nc]);
      }
    }
  }
  return null;
}

const path = solve();
if (!path) console.log("No way through!");
else {
  const steps = new Set(path.slice(1, -1));
  MAZE.forEach((row, r) => console.log([...row].map((ch, c) => (steps.has(`${r},${c}`) ? "•" : ch)).join("")));
  console.log(`\nShortest path: ${path.length - 1} steps`);
}

// Input (optional): board size from 4 to 9.
function solve(n) {
  const solutions = [], cols = [];
  const safe = (row, col) => cols.every((c, r) => c !== col && Math.abs(c - col) !== row - r);
  (function place(row) {
    if (row === n) { solutions.push([...cols]); return; }
    for (let col = 0; col < n; col++) {
      if (safe(row, col)) { cols.push(col); place(row + 1); cols.pop(); }
    }
  })(0);
  return solutions;
}

