const PUZZLE = [
  "530070000", "600195000", "098000060",
  "800060003", "400803001", "700020006",
  "060000280", "000419005", "000080079",
];

function options(grid, r, c) {
  const used = new Set([...grid[r], ...grid.map((row) => row[c])]);
  const br = Math.floor(r / 3) * 3, bc = Math.floor(c / 3) * 3;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) used.add(grid[br + i][bc + j]);
  return [1, 2, 3, 4, 5, 6, 7, 8, 9].filter((d) => !used.has(d));
}

let tries = 0;
function solve(grid) {
  for (let r = 0; r < 9; r++) for (let c = 0; c < 9; c++) {
    if (grid[r][c] !== 0) continue;
    for (const digit of options(grid, r, c)) {
      tries++;
      grid[r][c] = digit;
      if (solve(grid)) return true;
      grid[r][c] = 0;
    }
    return false;
  }
  return true;
}

const draw = (grid) => grid.forEach((row, r) => {
  if (r % 3 === 0 && r) console.log("------+-------+------");
  console.log([0, 3, 6].map((i) => row.slice(i, i + 3).map((d) => d || "·").join(" ")).join(" | "));
});

const grid = PUZZLE.map((row) => [...row].map(Number));
draw(grid);
console.log(solve(grid) ? `\nSolved after trying ${tries} digits:\n` : "\nThis puzzle has no solution.");
draw(grid);

