function hanoi(n, from, to, spare) {
  if (n === 0) return;
  hanoi(n - 1, from, spare, to);
  pegs[to].push(pegs[from].pop());
  console.log(`Move ${++moves}: ${"ABC"[from]} → ${"ABC"[to]}`);
  draw();
  hanoi(n - 1, spare, to, from);
}

