// Roads between cities with their distances. Input (optional): start city, then destination.
const ROADS = [
  ["Amber", "Birch", 7], ["Amber", "Cedar", 9], ["Amber", "Fern", 14], ["Birch", "Cedar", 10],
  ["Birch", "Dune", 15], ["Cedar", "Dune", 11], ["Cedar", "Fern", 2], ["Dune", "Elm", 6], ["Elm", "Fern", 9],
];

const graph = {};
for (const [a, b, km] of ROADS) {
  (graph[a] = graph[a] || {})[b] = km;
  (graph[b] = graph[b] || {})[a] = km;
}

function shortest(start, goal) {
  const dist = Object.fromEntries(Object.keys(graph).map((c) => [c, Infinity]));
  const previous = {}, unvisited = new Set(Object.keys(graph));
  dist[start] = 0;
  while (unvisited.size) {
    const here = [...unvisited].reduce((a, b) => (dist[a] <= dist[b] ? a : b));   // closest unvisited city
    if (here === goal || dist[here] === Infinity) break;
    unvisited.delete(here);
    for (const [next, km] of Object.entries(graph[here])) {
      if (dist[here] + km < dist[next]) { dist[next] = dist[here] + km; previous[next] = here; }
    }
  }
  const path = [];
  for (let at = goal; at; at = previous[at]) path.unshift(at);
  return { km: dist[goal], path };
}

const cities = Object.keys(graph);
const pickCity = (text, fallback) => cities.find((c) => c.toLowerCase() === (text || "").trim().toLowerCase()) || fallback;
