function bankAccount(balance) {
  return {
    deposit(amount) { balance += amount; return balance; },
    withdraw(amount) { if (amount > balance) throw new Error("Not enough money"); balance -= amount; return balance; },
  };
}
const account = bankAccount(50);
console.log("Private balance:", account.deposit(25), account.withdraw(60), "direct access:", account.balance);

class Account {
  #balance = 0;                              // # makes a field truly private
  static count = 0;

  constructor(owner, balance = 0) {
    this.owner = owner;
    this.#balance = balance;
    this.history = [];
    Account.count++;
  }

  get balance() { return this.#balance; }

  deposit(amount) {
    if (amount <= 0) throw new RangeError("Deposit must be more than zero");
    this.#balance += amount;
    this.history.push(["deposit", amount]);
    return this;                             // returning this allows chaining
  }

  withdraw(amount) {
    if (amount > this.#balance) throw new Error(`${this.owner} only has $${this.#balance.toFixed(2)}`);
    this.#balance -= amount;
    this.history.push(["withdraw", amount]);
    return this;
  }

  toString() { return `${this.constructor.name}(${this.owner}, $${this.#balance.toFixed(2)})`; }
}

class SavingsAccount extends Account {
  constructor(owner, balance, rate = 0.04) { super(owner, balance); this.rate = rate; }
  addInterest() { return this.deposit(Math.round(this.balance * this.rate * 100) / 100); }
  withdraw(amount) {
    if (amount > 500) throw new Error("Savings withdrawals are limited to $500");
    return super.withdraw(amount);
  }
}

