// setTimeout works here, but waits are skipped: timers fire in order instantly.
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function download(name, ms, fail = false) {
  await sleep(ms);
  if (fail) throw new Error(`${name} failed to download`);
  return `${name}.zip`;
}

async function main() {
  console.log("One by one (each waits for the one before):");
  for (const [name, ms] of [["photos", 300], ["music", 200]]) console.log("  got", await download(name, ms));

  console.log("All at once (finished when the slowest is done):");
  console.log("  got", await Promise.all([download("photos", 300), download("music", 200), download("docs", 100)]));

  console.log("First one to finish wins:");
  console.log("  got", await Promise.race([download("slow", 500), download("fast", 50)]));

  console.log("Handling a failure with try/catch:");
  try { await download("broken", 100, true); }
  catch (e) { console.log("  caught:", e.message); }

  console.log("allSettled reports every result, good or bad:");
  const results = await Promise.allSettled([download("a", 10), download("b", 20, true)]);
  for (const r of results) console.log("  ", r.status, r.value || r.reason.message);

  console.log("Retrying until it works:");
  let attempt = 0;
  const flaky = async () => { if (++attempt < 3) throw new Error("try again"); return `worked on attempt ${attempt}`; };
  for (;;) { try { console.log("  ", await flaky()); break; } catch (e) { await sleep(100); } }
}

main().then(() => console.log("Done."));
