// A generator function pauses at each yield and continues when asked for the next value.
function* numbers(start = 1) { for (let n = start; ; n++) yield n; }
function* take(count, source) { for (const item of source) { if (count-- <= 0) return; yield item; } }
function* filter(test, source) { for (const item of source) if (test(item)) yield item; }
function* map(fn, source) { for (const item of source) yield fn(item); }

