class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseAge(text) {
  const age = Number(text);
  if (!Number.isInteger(age)) throw new ValidationError("age", `"${text}" isn't a whole number`);
  if (age < 0 || age > 130) throw new ValidationError("age", `${age} isn't a realistic age`);
  return age;
}

