// A tiny cache that forgets the oldest entry.
class LRU {
  constructor(limit) { this.limit = limit; this.items = new Map(); }
  get(key) { if (!this.items.has(key)) return undefined; const v = this.items.get(key); this.items.delete(key); this.items.set(key, v); return v; }
  set(key, value) { this.items.delete(key); this.items.set(key, value); if (this.items.size > this.limit) this.items.delete(this.items.keys().next().value); }
}
